<template><view class="association"><view class="notice">通过账号与四位登录码验证归属后，关联至当前班级。</view><text class="label">成长小主人账号 <text>*</text></text><input v-model="account" :disabled="busy||uncertain" maxlength="64" placeholder="请输入已有账号"/><text class="label">四位登录码 <text>*</text></text><input v-model="code" :disabled="busy||uncertain" type="number" password maxlength="4" placeholder="请输入4位登录码"/><view v-if="captchaRequired"><text class="label">图形验证码</text><view class="captcha"><input v-model="answer" :disabled="busy" placeholder="输入图中文字"/><image v-if="image" :src="image" mode="aspectFit" @tap="refreshCaptcha"/><button v-else :disabled="busy" @tap="refreshCaptcha">获取验证码</button></view></view><view class="consent"><checkbox :checked="consent" :disabled="busy" @tap="consent=!consent"/><text>我已阅读并同意</text><text class="link" @tap="readTerms">《用户协议》《隐私条款》</text></view><text v-if="error" class="error">{{error}}</text><button class="confirm" :disabled="completed||busy||uncertain" :loading="busy" @tap="submit">确认关联</button><text v-if="uncertain" class="error">操作结果待确认，请返回班级核对后再操作。</text></view></template>
<script setup lang="ts">
import {ref,watch,onBeforeUnmount} from 'vue';
import {classMemberApi} from '@/api/class-members';import {classAccountProof} from '@/models/class-account-proof';import {issueStudentCaptcha} from '@/api/auth';import {ApiError,request} from '@/api/http';import {getOrCreateDeviceId,getDeviceName} from '@/session/student-session';import {getOrganizationSession} from '@/session/organization-session';
const props=defineProps<{token:string;schoolId:string;classId:string}>();const emit=defineEmits<{(e:'linked'):void}>();
const completed=ref(false);
const account=ref(''),code=ref(''),answer=ref(''),image=ref(''),challenge=ref(''),consent=ref(false),busy=ref(false),uncertain=ref(false),error=ref(''),captchaRequired=ref(false);let revision=0,captchaRevision=0,alive=true;
function valid(){const org=uni.getStorageSync('lingdong.selected-organization') as {organizationId?:string;accessToken?:string}|undefined;return alive&&getOrganizationSession()?.accessToken===props.token&&org?.accessToken===props.token&&org?.organizationId===props.schoolId;}
function current(n:number){return n===revision&&valid();}
function clear(){completed.value=false;++revision;++captchaRevision;account.value='';code.value='';answer.value='';image.value='';challenge.value='';consent.value=false;captchaRequired.value=false;busy.value=false;uncertain.value=false;error.value='';}
async function refreshCaptcha(){if(!valid()||!account.value.trim())return;const n=revision,requestId=++captchaRevision,requestedAccount=account.value.trim();try{const result=await issueStudentCaptcha(requestedAccount,getOrCreateDeviceId());if(!current(n)||requestId!==captchaRevision||account.value.trim()!==requestedAccount)return;challenge.value=result.challengeId;image.value=result.imageBase64;answer.value='';}catch(e){if(current(n)&&requestId===captchaRevision&&account.value.trim()===requestedAccount)error.value=e instanceof Error?e.message:'验证码获取失败';}}
async function readTerms(){try{const terms=await request<{content:string}>('/public/registration/agreement');if(valid())await uni.showModal({title:'用户协议与隐私条款',content:terms.content,showCancel:false});}catch(e){if(valid())error.value=e instanceof Error?e.message:'协议读取失败';}}
async function submit(){if(completed.value||busy.value||uncertain.value||!valid())return;const n=revision;let attempted=false;error.value='';try{const proof=classAccountProof({studentAccount:account.value,loginCode:code.value,consent:consent.value,deviceId:getOrCreateDeviceId(),deviceName:getDeviceName(),captchaRequired:captchaRequired.value,captchaChallengeId:challenge.value,captchaAnswer:answer.value});busy.value=true;attempted=true;const result=await classMemberApi.associateAccount(props.token,props.schoolId,props.classId,proof);if(!current(n))return;if(result.enrollmentOrganizationId!==props.schoolId||!result.currentClassOrganizationIds.includes(props.classId))throw Error('关联结果范围不一致，请返回核对');code.value='';answer.value='';completed.value=true;emit('linked');}catch(e){if(!current(n))return;error.value=e instanceof Error?e.message:'关联失败';if(attempted){code.value='';answer.value='';if(e instanceof ApiError&&e.code==='CAPTCHA_REQUIRED'){captchaRequired.value=true;await refreshCaptcha();}else if(!(e instanceof ApiError)||e.statusCode>=500)uncertain.value=true;}}finally{if(n===revision)busy.value=false;}}
watch(()=>[props.token,props.schoolId,props.classId],clear);watch(account,()=>{++captchaRevision;code.value='';challenge.value='';image.value='';answer.value='';});onBeforeUnmount(()=>{alive=false;clear();});
</script>
<style scoped>.association{color:#193e30}.notice{padding:22rpx;border-radius:14rpx;background:#edf6ff;color:#326f9f;font-size:25rpx;line-height:1.6;margin-bottom:24rpx}.label{display:block;font-size:28rpx;margin:24rpx 0 14rpx}.label text{color:#ba5145}input{height:76rpx;padding:0 20rpx;background:#fafcfb;border:1rpx solid #dfe6e1;border-radius:14rpx;font-size:27rpx}.consent{display:flex;align-items:center;white-space:nowrap;gap:3rpx;font-size:21rpx;margin-top:26rpx}.consent checkbox{transform:scale(.7);width:42rpx}.link{color:#167bbc}.confirm{background:#155e45;color:white;border-radius:18rpx;line-height:86rpx;font-size:29rpx;margin-top:22rpx}.error{display:block;color:#b45445;font-size:25rpx;line-height:1.6;margin-top:18rpx}.captcha{display:flex;align-items:center;gap:14rpx}.captcha input{flex:1;min-width:0}.captcha image{width:220rpx;height:80rpx}button::after{border:0}</style>
